$spent = 0.0
foreach ($k in $t.Keys) {
  $body = @{ subject=$t[$k]; model="gpt-image-2"; width=1536; height=1024; exact_size=$true; raw=$true } | ConvertTo-Json -Compress
  try { $j = (RUN ("SHOW_IT " + $body)) | ConvertFrom-Json
    if ($j.payload.ok -and $j.payload.id) { $spent += [double]$j.payload.cost_usd; "  " + $k + " -> " + $j.payload.image_url } else { "  " + $k + " -> NOT DRAWN: " + $j.payload.error } } catch { "  " + $k + " -> NOT DRAWN: " + $_.Exception.Message } }
$b = [ordered]@{}
$b['Bad Bitch'] = 'A wide panoramic header banner for the "Bad Bitch" category of a tattoo website. On the right, a close-up real photograph, framed close from the waist up so the person fills the full height of the photo and the tattoo is large, sharp and easy to read: a fierce woman in her late twenties with long dark wavy hair and deep red lips, in a black corset top, looking back over her shoulder at the camera in moody low light. Her shoulder and upper arm carry a black-and-grey tattoo of Medusa with living serpents and crimson accents. On the left, on a dark smoky background, the words "Bad Bitch" written large in sharp gothic blackletter lettering in crimson and black, surrounded by dark tattoo art - a warrior queen in a battle crown, a coiled serpent with red peonies, a raven in flight, a cracked porcelain face, a blood-red gem in black filigree and a winged woman. The art fades softly into the photo through crimson ink smoke. Fierce, dark and glamorous, high detail. Only the words "Bad Bitch", no other text, no watermark, no logos.'
$b['Badass'] = 'A wide panoramic header banner for the "Badass" category of a tattoo website. On the left, a close-up real photograph, framed close from the waist up so the person fills the full height of the photo and the tattoo is large, sharp and easy to read: a heavily muscled bearded man in his thirties, shirtless in dramatic low light, turned three-quarters with a hard stare. His shoulder and arm carry a dense black-and-grey tattoo of a Spartan helmet above a battlefield with crimson accents. On the right, on a dark stormy background, the words "Badass" written large in heavy distressed iron lettering with red cracks glowing through, surrounded by epic tattoo art - a titan holding a cracked glowing globe, a lone samurai, a tiger smashing through a wall, a biomechanical spine of gears, a dragon coiled around a fortress and forked lightning. The art fades softly into the photo through dark storm smoke and embers. Intense, powerful and cinematic, high detail. Only the words "Badass", no other text, no watermark, no logos.'
foreach ($k in $b.Keys) {
  $body = @{ subject=$b[$k]; model="gpt-image-2"; width=2048; height=768; exact_size=$true; raw=$true } | ConvertTo-Json -Compress
  try { $j = (RUN ("SHOW_IT " + $body)) | ConvertFrom-Json
    if ($j.payload.ok -and $j.payload.id) { $spent += [double]$j.payload.cost_usd; "  BANNER " + $k + " -> " + $j.payload.image_url } else { "  BANNER " + $k + " -> NOT DRAWN: " + $j.payload.error } } catch { "  BANNER " + $k + " -> NOT DRAWN: " + $_.Exception.Message } }
